 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            if maxr - minr == 2 and maxc - minc == 2 and len(cells) == 9:
                obj = [row[minc:maxc + 1] for row in grid[minr:maxr + 1]]
                if len({v for row in obj for v in row}) == 3:
                    candidates.append(obj)
    if len(candidates) != 1:
        raise ValueError(f"Expected one three-color 3x3 object, found {len(candidates)}")
    return candidates[0]
